int searchAnswer(int lo, int hi) {
    int left = lo, right = hi;
    while (left <= right) {
        int mid = left + (right - left) / 2;
        if (check(mid)) {
            right = mid - 1;  // satisfies: try smaller
        } else {
            left = mid + 1;   // fails: try larger
        }
    }
    return left;  // first value where check() is true
}
